#include <stdio.h>
#include <string.h>
#include "config.h"

const char *greet(void);

int main(void) {
    const char *got = greet();
    const char *want = "Hello, " NAME "!";
    if (strcmp(got, want) != 0) {
        fprintf(stderr, "greet() = \"%s\", want \"%s\" (the CURRENT NAME, not a stale value)\n", got, want);
        return 1;
    }
    printf("PASS\n");
    return 0;
}
